  section_sequence, premium_cut, writer_metadata_fields, hard_rules)
select s.id, s.name, s.role, s.stated_read_length, s.access_tier, s.piece_type,
       s.section_sequence, s.premium_cut, s.writer_metadata_fields, s.hard_rules
  from jsonb_to_recordset('[{"id":"1a","name":"Feature long read","role":"The base chassis. Journalist-authored argument feature.","stated_read_length":{"readme":"~18 min","markup_byline":"21 MIN READ","markup_audio":"Listen · 21m","discrepancy":true},"access_tier":{"readme":"Metered","badge_in_markup":"PREMIUM (ink pill in the headline kicker row, not the masthead)","meter_state_shown":"3 / 3 FREE READS USED","effective":"metered — free reads counted, then a mid-article cut"},"piece_type":"FEATURE","section_sequence":[{"order":1,"region":"masthead","required":true,"contains":"Marsad wordmark + Arabic مرصد + divider + ''THE LONG READ'' eyebrow + right-aligned dateline ''SAT 4 JUL 2026 · 06:00 GST''","width":"full 1440, padding 0 34"},{"order":2,"region":"headline_block","required":true,"contains":"kicker row (diamond + ''ENERGY · SAUDI ARABIA'' + PREMIUM pill), h1 60px, standfirst 20px (max-width 780)","width":"max-width 1020, centred text"},{"order":3,"region":"master_photo","required":true,"contains":"image-slot lf-feature-hero, 1372x520 box on #e8e5dc with 1px #dcd8cc border; caption 11px #57534a (max-width 760) + right-aligned credit ''PHOTO · MARSAD DESK''; closes with a 1px bottom rule","width":"1372 full bleed inside page padding"},{"order":4,"region":"byline_bar","required":true,"contains":"42px monogram avatar, name + beat, mono meta line, action cluster (Save / Share / Listen · 21m / Follow 2222)","width":"max-width 1020"},{"order":5,"region":"body_rail_grid","required":true,"contains":"the two-column measure + rail region; everything below is inside it","width":"max-width 1160"},{"order":6,"region":"measure > standfirst_bullets","required":true,"contains":"''THE ARGUMENT IN THREE LINES'' label + exactly 3 square-bulleted 13.5px lines; framed by a 2px ink top rule and a 1px bottom rule"},{"order":7,"region":"measure > opening_paragraph","required":true,"contains":"drop-capped first paragraph"},{"order":8,"region":"measure > paragraph","required":true,"contains":"argument prose"},{"order":9,"region":"measure > inline_ticker_card","required":false,"contains":"ticker + EN/AR company name | LAST price + change | MARSAD SCORE + verdict | 150x42 sparkline + 12M relative vs TASI + PT and upside + ''Open workspace'' CTA; 1px ink border, internal 1px #dcd8cc dividers"},{"order":10,"region":"measure > paragraph","required":true,"contains":"the disagreement / against-consensus paragraph"},{"order":11,"region":"measure > pull_quote","required":false,"contains":"27px italic quote + mono attribution line"},{"order":12,"region":"measure > exhibit_1","required":true,"contains":"area+line chart (640x220 viewBox, 5 gridlines, shaded polygon, end dot, dashed event marker), x-axis year labels, 3-part footnote row, provenance strip (green diamond, lake object id, 29 quarters, verifying agent + time, ''DOWNLOAD SERIES'')"},{"order":13,"region":"measure > paragraph","required":true,"contains":"learning-curve paragraph"},{"order":14,"region":"measure > stat_strip","required":false,"contains":"4 equal cells (label + Newsreader 27px value; third value tinted green) + a mono provenance caption naming two lake objects and flagging the desk computation"},{"order":15,"region":"measure > section_subhead","required":false,"contains":"Newsreader 25px 700 ''What the market is still pricing''"},{"order":16,"region":"measure > paragraph","required":true,"contains":"reverse-DCF setup paragraph"},{"order":17,"region":"measure > exhibit_2","required":false,"contains":"5-row horizontal bar sensitivity (label 210px + bar + value + delta), grey bar = base, ink = upside, red = downside; footnote; provenance strip naming the desk model id, 41 lake objects, reviewer, ''OPEN MODEL''"},{"order":18,"region":"measure > paragraph","required":true,"contains":"risk-to-the-view paragraph"},{"order":19,"region":"measure > exhibit_3_scenario_table","required":false,"contains":"grid 1.4fr 90px 90px 100px 1fr: scenario / FY28 EPS / target / total return / trigger to watch; 3 rows, base case row shaded #f6f4ee"},{"order":20,"region":"measure > premium_cut","required":true,"contains":"sc-if isFree: blurred 2-paragraph teaser + 120px scrim, then the paywall card (meter chip, offer headline, 3 benefit lines, trial CTA, billing line + Sign in)"},{"order":21,"region":"measure > premium_continuation","required":true,"contains":"sc-if isPremium: 2 closing paragraphs + END row (mono ''END'' + diamond + author position disclosure)"},{"order":22,"region":"measure > method_disclosure_footer","required":true,"contains":"METHOD column + DISCLOSURE column"},{"order":23,"region":"rail","required":false,"contains":"sc-if showRail; sticky top:20px; 4 stacked modules (see rail)"}],"premium_cut":{"present":true,"falls_after":"Exhibit 3 (the scenario table) and the risk paragraph — roughly two thirds through the argument, before the dividend / free-cash-flow build","mechanism":"sc-if isFree renders a 2-paragraph blurred teaser (blur 3.5px, 120px gradient scrim) then the paywall card; sc-if isPremium renders the real continuation","meter_rule":"3 / 3 FREE READS USED — metered access, cut fires when the meter is exhausted","paywall_copy":{"eyebrow":"CONTINUE WITH MARSAD PREMIUM","headline":"The ten-year build, the tariff case and the model file are for members.","benefits":["Every premium note & model file","Marsad Score on 812 GCC stocks","Screens, alerts & datapoint feeds"],"cta":"Start 14-day trial — SAR 89/mo","fine_print":"Billed annually · cancel anytime · Sign in"}},"writer_metadata_fields":{"identity":["section_kicker","access_tier","masthead_section_label","publish_datetime","updated_datetime","read_time_minutes","audio_duration_minutes"],"headline_set":["headline","standfirst","argument_bullets[3]"],"hero":["hero_image_asset","hero_caption","hero_credit","hero_dimensions"],"author":["author_name","author_initials","author_beat","author_position_disclosure"],"entity":["primary_ticker","company_name_en","company_name_ar","last_price","day_change_pct","marsad_score","marsad_score_verdict","sparkline_series","relative_performance_12m_vs_index","price_target","implied_upside_pct","workspace_link"],"narrative":["body_paragraphs[]","drop_cap_flag_on_first","section_subheads[]","pull_quote_text","pull_quote_attribution"],"exhibits":["exhibit_number","exhibit_title","unit_or_axis_note","chart_type","series_data","annotation_markers","footnote_lines[]","provenance.lake_object_ids[]","provenance.record_count","provenance.verifying_agent","provenance.verified_at","provenance.source_statement","provenance.is_desk_computation","provenance.action_label + link"],"stat_strip":["4 x {label, value, tone}"],"scenario_table":["rows[] {scenario, eps, target, total_return, trigger_to_watch}","highlight_row_index"],"paywall":["teaser_paragraphs[2]","meter_used","meter_limit","paywall_eyebrow","paywall_headline","benefit_lines[3]","plan_price","trial_days","billing_note"],"closing":["premium_continuation_paragraphs[]","end_label","author_position_line","method_copy","disclosure_copy","regulator","legal_entity"],"rail":["key_numbers[4] {label, value}","in_this_piece[] {ticker, name, change_pct}","how_built_narrative","agent_chips[]","human_editor_chip","related[] {title, tier, type, date}"]},"hard_rules":["1a is the chassis — build it first; all other types are furniture swaps on this grid.","The measure is fixed; body copy never reflows to the full 1440px.","Exhibits span gutter + measure, never the rail.","The rail is the only independently scrolling column.","Exactly three standfirst bullets under ''THE ARGUMENT IN THREE LINES''.","Every figure cites a verified data-lake object; desk computations must be labelled as such on the exhibit.","Corrections are appended, never silent.","Analysts may not hold positions in covered names; the author''s position is stated in the end matter.","The metered cut must fall after the reader has seen substantive evidence (here: three exhibits and the scenario table)."]},{"id":"1b","name":"Research note (analyst note with a formal call)","role":"The analyst''s output, not the journalist''s. Same chassis, furniture swapped to carry a formal call.","stated_read_length":{"readme":"~14 min","markup_masthead":"24 MIN","discrepancy":true},"access_tier":{"readme":"Premium","badge_in_markup":"PREMIUM ink pill in the masthead","effective":"premium — whole document gated; there is no in-page cut and no isFree/isPremium branch in this file"},"piece_type":"NOTE","section_sequence":[{"order":1,"region":"masthead","required":true,"contains":"Marsad wordmark (no Arabic mark) + divider + ''RESEARCH NOTE · SECTOR'' + PREMIUM pill + right-aligned ''NOTE 2026-114 · 28 JUN 2026 · 24 MIN''"},{"order":2,"region":"title_band > title_cell","required":true,"contains":"kicker (diamond + ''GCC BANKS · SECTOR INITIATION UPDATE''), h1 44px, thesis dek 17.5px (max-width 660), analyst byline row with rank/track record and PDF / Model .xlsx / Follow analyst actions","width":"1060px cell, padding 34px 34px 26px"},{"order":3,"region":"title_band > rating_panel","required":true,"contains":"ink panel: ''TOP PICK · RATING CHANGE'' label, ticker + company, rating chip + prior rating, 2-cell grid (PRICE TARGET + prior / IMPLIED UPSIDE + last price), 3-cell multiple strip (FY27E P/E, P/B, YLD), Marsad Score block labelled ''INDEPENDENT OF THIS CALL'' with quant verdict + agreement flag","width":"380px, padding 28px 30px"},{"order":4,"region":"whats_changed","required":true,"contains":"1px ink box: 150px ink label cell (''WHAT''S CHANGED'' + since-date) + 3 numbered items, index tinted green (supports) or red (argues against)","width":"1092"},{"order":5,"region":"master_exhibit","required":true,"contains":"EXHIBIT 1 · MASTER — 1050x300 bubble scatter (bubble = market cap, quadrant crosshairs, per-name labels, colour by rating), rating legend row + takeaway line, provenance strip","width":"1092 — breaks the measure entirely"},{"order":6,"region":"prose_column (left of 2-col)","required":true,"contains":"3 body paragraphs + a 21px pull quote"},{"order":7,"region":"coverage_table (right of 2-col)","required":true,"contains":"EXHIBIT 2 ''Coverage & ratings'' — grid 58px 1fr 88px 60px 58px 54px: ticker / rating / PT (was) / upside / P/E / NIM; 5 of 14 rows shown, raised ratings flagged with a green triangle, top two rows shaded; footnote ''FULL TABLE IN THE PDF''"},{"order":8,"region":"quarterly_metric_table","required":true,"contains":"EXHIBIT 3 — grid 180px repeat(8,1fr): 8 quarters x 3 metric rows (Sector NIM shaded, CASA share, Cost of funds); current quarters bolded, estimate column labelled Q3 ''26E in muted grey; provenance strip stating the estimate is labelled as such everywhere it appears","width":"1092"},{"order":9,"region":"valuation_bridge (left of 2-col)","required":true,"contains":"''Valuation — how we get to 112'': 5 label/value rows ending in a 2px-ruled price target row"},{"order":10,"region":"risks_and_falsifiers (right of 2-col)","required":true,"contains":"''Risks to the call'' — 3 red-diamond items — followed by the falsifier box (''What would change our view: …'', 3px ink left rule on #f6f4ee)"},{"order":11,"region":"compliance_footer","required":true,"contains":"single mono strip: note id, published timestamp, rules check score, positions statement, ratings definitions, track-record immutability, advice disclaimer, regulator and entity","width":"1092"}],"premium_cut":{"present":false,"rule":"The whole note is premium; access is enforced at document level, not by an in-article cut. No isFree/isPremium branches and no paywall card exist in this file."},"writer_metadata_fields":{"identity":["note_id","publish_date","publish_time + timezone","read_time_minutes","masthead_section_label","access_tier","section_kicker"],"call":["top_pick_ticker","company_name","rating","prior_rating","price_target","prior_price_target","implied_upside_pct","last_price","currency","fy_forward_pe","price_to_book","dividend_yield","marsad_score","marsad_score_verdict","score_agreement_flag","rating_change_label"],"thesis":["thesis_statement","headline"],"analyst":["analyst_name","analyst_initials","analyst_title","analyst_rank","win_rate_pct","names_covered_count","analyst_email"],"whats_changed":["reference_note_date","items[3] {index, tone(supports|against), text}"],"exhibits":["master_exhibit {title, axis_labels, bubble_metric, points[] {ticker, x, y, size, rating_class}, legend, takeaway_line}","coverage_table rows[] {ticker, rating, price_target, prior_price_target, upside_pct, pe, nim, raised_flag}","coverage_footnote {rows_shown, rows_total, where_full_table_lives}","quarterly_table {metric_rows[3], periods[8], estimate_period_flags, current_period_flags}","provenance per exhibit {lake_object_ids, derivation, recompute_trigger, estimate_labelling_rule}"],"narrative":["body_paragraphs[]","pull_quote_text"],"valuation":["forward_eps","target_multiple + context","sustainable_roe","cost_of_equity","price_target"],"risk":["risks[3]","falsifiers_statement (mandatory)"],"compliance":["rules_check_score","positions_disclosed","ratings_definitions","track_record_policy","advice_disclaimer","regulator","legal_entity"]},"hard_rules":["The rating header comes first, above the headline, because it is the thing being asserted.","The standfirst is replaced by a thesis box (BLK-THESIS): the claim, stated once, before any argument begins.","A falsifiers block (BLK-FALSIFY) is MANDATORY near the end. A note without stated falsifiers does not pass the ruleset.","Disclosure is structural, not a footnote: holdings position and coverage status sit in the byline bar.","The rail carries valuation scaffolding, not reading furniture.","The Marsad Score is shown as independent of the analyst''s call and labelled so.","Estimates are labelled E everywhere they appear (stated on the quarterly-table provenance strip).","Ratings are defined as 12-month total return vs the venue index: Overweight >10%, Neutral ±10%, Underweight <−10%.","Track records are public and cannot be edited retroactively.","A rules check must be run and its score published (6/6 PASSED)."]},{"id":"3a","name":"Sector deep dive (multi-part series investigation)","role":"The heaviest type in the system; signals its weight three ways (reverse headline, series position, opening contract).","stated_read_length":{"readme":"~40 min","markup_byline":"40 MIN READ","markup_audio":"Listen · 40m","markup_rail":"CHAPTERS · 40 MIN","chapter_minutes_sum":40,"discrepancy":false},"access_tier":{"readme":"Premium","badge_in_markup":"PREMIUM ink pill in the masthead","effective":"premium with a chapter-level cut — three chapters free, chapter 4 and the database gated"},"piece_type":"DEEP DIVE","section_sequence":[{"order":1,"region":"masthead","required":true,"contains":"Marsad wordmark + divider + ''DEEP DIVE · FOUR CHAPTERS'' + PREMIUM pill + right-aligned SERIES POSITION ''SERIES: THE WATER ECONOMY · PART 2 OF 3'' (replaces the dateline)"},{"order":2,"region":"title_band_reverse","required":true,"contains":"ink band: kicker with pale diamond, h1 58px reversed on ink, standfirst 20px #a8a396 (max-width 820), then a rule and the byline row rendered in reverse (pale avatar, name + beat, meta ''27 JUL 2026 · 40 MIN READ · 9 EXHIBITS · MODEL FILE + PLANT DATABASE'', actions Save / Listen · 40m / Download database with an inverted primary button)"},{"order":3,"region":"master_photo","required":true,"contains":"image-slot lf-dd-hero 1372x440 (borders left/right/bottom only — the ink band supplies the top edge), caption + ''PHOTO · MARSAD DESK'' credit"},{"order":4,"region":"body_rail_grid","required":true,"contains":"measure 762 + rail 296"},{"order":5,"region":"measure > what_this_establishes","required":true,"contains":"1px ink box on #f6f4ee: ''WHAT THIS DEEP DIVE ESTABLISHES'' + a 2x2 grid of 4 numbered claims the reader will be able to make"},{"order":6,"region":"measure > chapter_1_heading","required":true,"contains":"2px ink top rule + 44px pale chapter number + ''CHAPTER ONE'' eyebrow + 30px display title"},{"order":7,"region":"measure > chapter_1_body","required":true,"contains":"drop-capped paragraph + 1 paragraph"},{"order":8,"region":"measure > exhibit_1","required":true,"contains":"Anatomy exhibit — proportional stacked bar 68% capacity / 24% pass-through / 8% O&M (ink / #a8a396 / #e3dfd4) + a 3-column ''who bears what'' row keyed to the same three fills; provenance strip flagging the split as a desk average across 19 contracts"},{"order":9,"region":"measure > chapter_2_heading","required":true,"contains":"chapter rule + number 02 + ''CHAPTER TWO'' + title"},{"order":10,"region":"measure > chapter_2_body","required":true,"contains":"paragraph + 27px pull quote (no attribution)"},{"order":11,"region":"measure > exhibit_2","required":true,"contains":"Paired-bar exhibit — 5 operators, grey bar = project debt spread, ink bar = implied equity COE, value pair per row; legend + median-gap note; provenance strip separating verified market data from the desk reverse-DCF model"},{"order":12,"region":"measure > chapter_3_heading","required":true,"contains":"chapter rule + number 03 + title"},{"order":13,"region":"measure > chapter_3_body","required":true,"contains":"paragraph introducing the table"},{"order":14,"region":"measure > exhibit_3","required":true,"contains":"Four-market offtaker table — grid 118px 1.1fr 78px 92px 82px 1fr: market / offtaker / plants / contracted / RISK chip / what to watch; risk chips green #0f5f31 (LOWEST, LOW), amber #c9a227 (MEDIUM), red #c0342b (HIGHEST); mandatory footnote ''RISK RANKING IS A DESK ASSESSMENT OF PAYMENT STRUCTURE, NOT A CREDIT RATING''"},{"order":15,"region":"measure > chapter_4_heading","required":true,"contains":"chapter rule + number 04 + title"},{"order":16,"region":"measure > chapter_4_opening","required":true,"contains":"one free paragraph before the cut"},{"order":17,"region":"measure > premium_cut","required":true,"contains":"sc-if isFree: 2 blurred paragraphs + 120px scrim, then the paywall card with the chapter-progress chip"},{"order":18,"region":"measure > premium_continuation","required":true,"contains":"sc-if isPremium: closing paragraph + ''END OF PART 2'' row with the next-part title and publication date"},{"order":19,"region":"measure > method_disclosure_footer","required":true,"contains":"METHOD (build provenance + the desk-assessment caveat restated) + DISCLOSURE"},{"order":20,"region":"rail","required":false,"contains":"sc-if showRail; sticky chapter navigator + 5 further modules"}],"premium_cut":{"present":true,"falls_at":"Chapter 4 — after the chapter-4 heading and its first paragraph","stated_rule":"R-09: the cut falls at chapter 4, after three complete chapters, so the reader has seen the work before the wall","progress_chip_in_markup":"2 OF 4 CHAPTERS READ","mechanism":"identical to 1a: sc-if isFree renders 2 blurred paragraphs (blur 3.5px) + 120px scrim + paywall card; sc-if isPremium renders the real closing paragraph and end matter","paywall_copy":{"eyebrow":"CHAPTERS 4 & THE PLANT DATABASE ARE FOR MEMBERS","headline":"The 61-plant database, the membrane schedule and six repriced models.","benefits":["All four chapters & 9 exhibits","Plant-level database (.xlsx)","Part 3 when it publishes"],"cta":"Start 14-day trial — SAR 89/mo","fine_print":"Billed annually · cancel anytime · Sign in"},"note":"The README says the cut follows three complete chapters while the chip reads ''2 OF 4 CHAPTERS READ'' — reconcile the counter semantics (chapters completed vs chapters fully unlocked) before build."},"writer_metadata_fields":{"series":["series_name","part_number","parts_total","prior_part_title","next_part_title","next_part_publish_date","series_parts[] {label, title, state}"],"identity":["section_kicker","access_tier","masthead_section_label (DEEP DIVE · FOUR CHAPTERS)","publish_date","read_time_minutes","exhibit_count","attachments[]"],"headline_set":["headline (reverse on ink)","standfirst"],"hero":["hero_image_asset","hero_caption","hero_credit","hero_dimensions 1372x440"],"author":["author_name","author_initials","author_beat"],"contract":["establishes_items[4] {index, claim}"],"chapters":["chapters[4] {number, ordinal_word, display_title, rail_short_title, minutes, is_current}","total_minutes (must equal the sum of chapter minutes)"],"exhibits":["stacked_bar {segments[3] {label, pct, fill, description}, who_bears_what[3]}","paired_bars {rows[] {entity, debt_rate, equity_rate, debt_bar_px, equity_bar_px}, legend, median_gap, widest, narrowest}","risk_table {rows[] {market, offtaker, plants, contracted_value, risk_level, risk_chip_colour, what_to_watch}, mandatory_desk_assessment_footnote}","provenance per exhibit {lake_object_ids, synthesis_method, desk_computation_flag, model_id}"],"narrative":["chapter_body_paragraphs[]","drop_cap_flag (chapter one only)","pull_quote_text"],"paywall":["teaser_paragraphs[2]","chapters_read","chapters_total","paywall_eyebrow","paywall_headline","benefit_lines[3]","plan_price","trial_days"],"rail":["scope_panel[4] {label, value}","names_in_scope[] {ticker, name, change_pct}","how_built_narrative","agent_chips[]","human_byline_chip"],"closing":["premium_continuation_paragraph","end_of_part_label","method_copy","disclosure_copy"]},"hard_rules":["Headline is set in reverse on ink, not paper. Reserved for series work.","Series position appears in the masthead AND the rail.","A ''what this establishes'' contract opens the piece — state the payoff before demanding forty minutes.","Four numbered chapters, each with its own display heading and its own minute count in the rail.","The rail is a chapter navigator, not a contents list.","R-06: the offtaker table''s risk column is explicitly labelled a desk assessment of payment structure, not a credit rating — and is re-stated in the METHOD footer.","R-09: the cut falls at chapter 4, after three complete chapters, so the reader sees the work before the wall.","Exhibits carry the argument (stacked bar for the WPA anatomy, paired bars for the discount-rate gap, four-market offtaker table).","Chapter minutes must sum to the stated total read time (9+11+8+12 = 40).","The masthead dateline slot is given over to the series position."]},{"id":"3b","name":"Explainer (mechanism teaching)","role":"The inverse of a research note. No byline furniture, no thesis, no rating, because it asserts nothing. The free acquisition surface.","stated_read_length":{"readme":"~11 min","markup_masthead":"11 MIN","discrepancy":false},"access_tier":{"readme":"Free","badge_in_markup":"FREE TO READ (outlined chip, 1px #cfcabe, no ink fill)","effective":"free — no meter, no cut, no premium branch"},"piece_type":"EXPLAINER","section_sequence":[{"order":1,"region":"masthead","required":true,"contains":"Marsad wordmark + divider + ''LEARN · EXPLAINER'' + FREE TO READ chip + right-aligned ''EVERGREEN · REVIEWED 12 JUL 2026 · 11 MIN'' (review date, NOT a publication timestamp)"},{"order":2,"region":"headline_block","required":true,"contains":"kicker (diamond + ''CORPORATE ACTIONS · LEVEL 1'' — topic + difficulty level), h1 52px left-aligned, standfirst 19px; all inside an 840px block. No byline, no avatar, no actions."},{"order":3,"region":"hero_diagram","required":true,"contains":"The explainer hero is a DIAGRAM, not a photo: a 1px ink box on #f6f4ee with an ink header (''THE TIMELINE'' / ''Four dates, in the order they occur'' / right-aligned instrument + period + DPS), a 4-column equal-flex timeline, and a ''THE ONE-LINE VERSION'' summary row under a 1px rule","width":"1112 — breaks the measure entirely"},{"order":4,"region":"body_rail_grid","required":true,"contains":"measure 758 (text capped 740) + rail 300"},{"order":5,"region":"measure > section_subhead","required":true,"contains":"Newsreader 26px 700 ''Why the price drops on the ex-date''"},{"order":6,"region":"measure > explanation_paragraphs","required":true,"contains":"2 paragraphs of mechanism prose"},{"order":7,"region":"measure > worked_example","required":true,"contains":"Exhibit-framed ''WORKED EXAMPLE'' on 1,000 shares of a real ticker: 3-column grid (1.3fr 1fr 1fr) — position / close before / open on ex — with 4 rows (share price, value of position, dividend receivable, TOTAL) and a closing note; the total row is shaded and settles the point"},{"order":8,"region":"measure > failure_modes","required":true,"contains":"Newsreader 26px subhead ''Three ways this trips people up'' + exactly 3 numbered items {title 14px bold, explanation 12.5px}, item 3 carrying a cross-link to a separate explainer"},{"order":9,"region":"measure > what_this_is_not","required":true,"contains":"3px ink left rule on #f6f4ee: an explicit refusal to endorse the strategy the mechanism enables"},{"order":10,"region":"measure > review_footer","required":true,"contains":"''REVIEWED BY THE DESK'' — evergreen cadence statement, last review date + outcome, next review date; plus two chips (◆ WRITER-3 DRAFT, DESK VERIFIED). Replaces the METHOD/DISCLOSURE footer of 1a."},{"order":11,"region":"rail","required":false,"contains":"sc-if showRail; sticky; 4 modules"}],"premium_cut":{"present":false,"rule":"Free tier by design — this is the acquisition surface. No meter, no blur, no paywall card, and no isFree/isPremium branches in the file."},"writer_metadata_fields":{"identity":["topic_category","difficulty_level (L1/L2)","masthead_section_label (LEARN · EXPLAINER)","access_tier (FREE TO READ)","evergreen_flag","review_date","next_review_date","read_time_minutes"],"headline_set":["headline","standfirst"],"timeline":["instrument_context {ticker, company, period, dividend_per_share, currency}","stages[4] {index, name, date, description, is_critical}","critical_stage_index (exactly one)","one_line_version"],"explanation":["section_subhead","mechanism_paragraphs[]"],"worked_example":["share_count","ticker","column_labels {before, after}","rows[] {label, before_value, after_value}","dividend_amount","total_row {before, after}","closing_note","counterfactual_note (what happens if you buy on the ex-date)"],"failure_modes":["items[3] {index, title, explanation, optional_cross_link {label, target}}"],"refusal":["what_this_is_not_copy"],"review":["review_cadence_months","last_review_date","last_review_outcome","next_review_date","writer_agent_chip","verifier_chip"],"rail":["on_this_page[] {label, anchor, is_current}","glossary_terms[] {term, definition}","use_it_now {eyebrow, headline, body, cta_label, cta_target}","next_in_learn[] {level, title, target}"]},"hard_rules":["No byline furniture, no thesis, no rating — the explainer asserts nothing.","Opens on the mechanism: a four-date timeline is the hero, not a photo.","EXACTLY ONE timeline stage is in red, always — the date that costs money if missed.","The worked example uses round numbers and a real ticker, and ends in a total row that settles the point.","Exactly three named failure modes.","A ''what this is not'' box is required: an explainer that teaches a mechanism must decline to recommend using it.","Evergreen — it carries a review date, not a timestamp. Re-verified every six months and re-dated when venue rules change. A stale explainer is worse than none.","Free tier by design; this is the acquisition surface, so no meter and no cut.","The glossary (BLK-GLOSSARY) is auto-assembled from BLK-TERM instances in the body, not hand-authored.","Difficulty level is declared in the kicker and carried through to the ''Next in Learn'' ladder."]}]'::jsonb) as s(
    id text, name text, role text, stated_read_length text, access_tier jsonb, piece_type text,
    section_sequence jsonb, premium_cut jsonb, writer_metadata_fields jsonb, hard_rules jsonb)
on conflict (id) do update set
  name = excluded.name, role = excluded.role, stated_read_length = excluded.stated_read_length,
  access_tier = excluded.access_tier, piece_type = excluded.piece_type,
  section_sequence = excluded.section_sequence, premium_cut = excluded.premium_cut,
  writer_metadata_fields = excluded.writer_metadata_fields, hard_rules = excluded.hard_rules,
  updated_at = now();

do $$ declare v int; begin
  select count(*) into v from ops.article_templates;
  if v <> 4 then raise exception 'expected 4 article templates, got %', v; end if;
  raise notice 'article_templates: %', v;
end $$;
